import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;

public class MistSpan {
    static final int ALIGN = 32;
    static final int PIN_SIZE = 48;

    public static byte[] tint_k(Path silo, byte[] wanted) throws Exception {
        byte[] pins = Files.exists(silo.resolve("pin.bin"))
                ? Files.readAllBytes(silo.resolve("pin.bin")) : new byte[0];
        byte[] blob = Files.exists(silo.resolve("blob.bin"))
                ? Files.readAllBytes(silo.resolve("blob.bin")) : new byte[0];
        for (int i = 0; i + PIN_SIZE <= pins.length; i += PIN_SIZE) {
            ByteBuffer bb = ByteBuffer.wrap(pins, i, PIN_SIZE);
            byte[] magic = new byte[4];
            bb.get(magic);
            long off = bb.getLong();
            int len = bb.getInt();
            int crc = bb.getInt();
            byte[] id = new byte[16];
            bb.get(id);
            if (isMagic(magic) && same(id, wanted)) {
                byte[] payload = validPayload(blob, off, len, crc, id);
                if (payload != null) {
                    return payload;
                }
            }
        }
        return new byte[0];
    }

    static byte[] validPayload(byte[] blob, long off, int len, int crc, byte[] id) throws Exception {
        if (off < 0 || off > Integer.MAX_VALUE || len < 0) return null;
        long rec = 4L + len;
        long pad = (ALIGN - (rec % ALIGN)) % ALIGN;
        long end = off + rec + pad;
        if (end < off || end > blob.length || off + 4L > blob.length) return null;
        int pos = (int) off;
        if (ByteBuffer.wrap(blob, pos, 4).getInt() != len) return null;
        byte[] payload = new byte[len];
        System.arraycopy(blob, pos + 4, payload, 0, len);
        if (allZero(payload) || Crc.of(payload) != crc || !same(idOf(payload), id)) return null;
        return payload;
    }

    static byte[] idOf(byte[] payload) throws Exception {
        byte[] digest = MessageDigest.getInstance("SHA-256").digest(payload);
        byte[] id = new byte[16];
        System.arraycopy(digest, 0, id, 0, id.length);
        return id;
    }

    static boolean isMagic(byte[] x) {
        return x.length == 4 && x[0] == 'P' && x[1] == 'N' && x[2] == '0' && x[3] == '1';
    }

    static boolean allZero(byte[] x) {
        if (x.length == 0) return false;
        for (byte b : x) if (b != 0) return false;
        return true;
    }

    static boolean same(byte[] x, byte[] y) {
        if (x.length != y.length) return false;
        for (int i = 0; i < x.length; i++) if (x[i] != y[i]) return false;
        return true;
    }
}
